const BANK_AT = '2026-01-01T00:00:00.000Z';
let bankIndex = 0;
function q(subject: SubjectId, chapterId: string, question: string, options: string[], answer: number, explanation?: string): QuizQuestion {
  bankIndex += 1;
  return {
    id: `seed-${String(300 + bankIndex)}`, subject, chapterId, question, options, answer, explanation,
    source: 'নমুনা ব্যাংক · অধ্যায়ভিত্তিক', createdAt: BANK_AT, bank: true,
  };
}

